//! # mosaic-emit-webcomponent — Emitting Web Components Custom Element classes.
//!
//! This crate is the Web Components backend for the Mosaic compiler. It
//! implements [`MosaicRenderer`] and is driven by [`MosaicVM`]. The output is a
//! JavaScript string containing a complete Custom Element class ready to be
//! registered with `customElements.define`.
//!
//! ## Output file structure
//!
//! ```javascript
//! // Auto-generated by mosaic-emit-webcomponent. Do not edit.
//!
//! class ProfileCard extends HTMLElement {
//!   // Only scalar primitive slots go here (text, number, bool, image, color).
//!   // list<T> and node slots are managed via JS property setters.
//!   static get observedAttributes() { return ['avatar-url', 'display-name']; }
//!
//!   constructor() {
//!     super();
//!     this.attachShadow({ mode: 'open' });
//!     this._avatarUrl = '';        // text/image slot → string backing field
//!     this._displayName = '';      // text slot
//!     this._items = [];            // list<text> slot → array backing field
//!   }
//!
//!   connectedCallback() { this._render(); }
//!   attributeChangedCallback(name, _oldVal, newVal) {
//!     this[`_${this._toCamel(name)}`] = newVal ?? '';
//!     this._render();
//!   }
//!
//!   // JS property setter for list and node slots.
//!   set items(val) { this._items = val ?? []; this._render(); }
//!
//!   _render() {
//!     this.shadowRoot.innerHTML = `
//!       <div style="display: flex; flex-direction: column;">
//!         <span>${this._displayName}</span>
//!         ${this._show ? `<span>Conditional content</span>` : ''}
//!         ${this._items.map(item => `<li>${item}</li>`).join('')}
//!       </div>
//!     `;
//!   }
//!
//!   _escape(s) {
//!     return String(s)
//!       .replace(/&/g, '&amp;')
//!       .replace(/</g, '&lt;')
//!       .replace(/>/g, '&gt;')
//!       .replace(/"/g, '&quot;');
//!   }
//! }
//! customElements.define('profile-card', ProfileCard);
//! ```
//!
//! ## Architecture: fragment accumulation
//!
//! The renderer accumulates `HtmlFragment` values rather than raw strings. During
//! `emit()`, these fragments are serialized into a JavaScript template literal
//! body. `WhenOpen`/`WhenClose` become ternary expressions; `EachOpen`/`EachClose`
//! become `.map()` calls.
//!
//! ## Primitive node → HTML element mapping
//!
//! | Mosaic  | HTML tag                                   |
//! |---------|--------------------------------------------|
//! | Box     | `<div>`                                    |
//! | Column  | `<div style="display:flex;flex-direction:column">` |
//! | Row     | `<div style="display:flex;flex-direction:row">` |
//! | Text    | `<span>`                                   |
//! | Image   | `<img src="..." alt="...">`                |
//! | Spacer  | `<div style="flex:1">`                     |
//! | Scroll  | `<div style="overflow:auto">`              |
//! | Divider | `<hr>`                                     |
//! | Stack   | `<div style="position:relative">`          |
//! | Icon    | `<span class="icon">`                      |
//! | Grid    | `<table>` with slot-driven thead/tbody     |

use mosaic_vm::{EmitResult, MosaicRenderer, ResolvedProperty, ResolvedValue};
use mosaic_analyzer::{MosaicEmit, MosaicSlot, MosaicType};

// ===========================================================================
// HtmlFragment — typed pieces of the template literal body
// ===========================================================================

/// A typed fragment of the JavaScript template literal body.
///
/// Instead of accumulating raw strings, we accumulate fragments so that
/// `when` and `each` blocks can emit JS control-flow expressions rather than
/// literal HTML tags.
///
/// ## Fragment serialization rules
///
/// - `Raw(s)` → `s` appended verbatim.
/// - `WhenOpen(slot)` → `${this._<camel> ? \`` (starts a ternary expression).
/// - `WhenClose` → `` \` : ''}`` (closes the ternary's true branch).
/// - `EachOpen(slot, item)` → `${this._<camel>.map(<item> => \``
/// - `EachClose` → `` \`).join('')}``
///
/// The outer `_render()` method wraps all fragments in a single template literal.
#[derive(Debug, Clone)]
enum HtmlFragment {
    /// Literal HTML string piece.
    Raw(String),
    /// Beginning of `when` ternary: the slot name (kebab-case).
    WhenOpen(String),
    /// End of `when` ternary true branch.
    WhenClose,
    /// Beginning of `each` map call: (slot name, loop variable name).
    EachOpen(String, String),
    /// End of `each` map call.
    EachClose,
}

// ===========================================================================
// WebComponentRenderer
// ===========================================================================

/// The Web Components backend for the Mosaic compiler.
///
/// # Example
///
/// ```no_run
/// use mosaic_emit_webcomponent::WebComponentRenderer;
/// use mosaic_vm::MosaicVM;
/// use mosaic_analyzer::analyze;
///
/// let file = analyze("component Label { slot title: text; Text { content: @title; } }").unwrap();
/// let vm = MosaicVM::new(file);
/// let result = vm.run(WebComponentRenderer::new()).unwrap();
/// println!("{}", result.output);
/// ```
pub struct WebComponentRenderer {
    component_name: String,
    slots: Vec<MosaicSlot>,
    /// Stack of open element frames while the VM traverses nodes depth-first.
    /// Each frame holds the fragments accumulated inside that element.
    stack: Vec<HtmlFrame>,
    /// Fragments accumulated at the root level (outside any open frame).
    root_frags: Vec<HtmlFragment>,
}

/// A single open element frame on the traversal stack.
struct HtmlFrame {
    /// The HTML close tag to emit after all children (empty for self-closing).
    close_tag: String,
    /// Fragments accumulated inside this element.
    inner: Vec<HtmlFragment>,
}

impl WebComponentRenderer {
    /// Create a new `WebComponentRenderer`.
    pub fn new() -> Self {
        Self {
            component_name: String::new(),
            slots: Vec::new(),
            stack: Vec::new(),
            root_frags: Vec::new(),
        }
    }

    // -----------------------------------------------------------------------
    // Name conversion helpers
    // -----------------------------------------------------------------------

    /// Convert a PascalCase component name to kebab-case for the custom element tag.
    ///
    /// Examples:
    ///   `ProfileCard` → `profile-card`
    ///   `Button` → `button`
    fn to_element_tag(name: &str) -> String {
        let mut result = String::new();
        for (i, ch) in name.chars().enumerate() {
            if ch.is_uppercase() && i > 0 {
                result.push('-');
            }
            result.push(ch.to_ascii_lowercase());
        }
        result
    }

    /// Convert a kebab-case slot name to camelCase for JavaScript backing fields.
    ///
    /// Examples:
    ///   `avatar-url` → `avatarUrl`
    ///   `display-name` → `displayName`
    ///   `items` → `items`
    fn to_camel_case(kebab: &str) -> String {
        let mut result = String::new();
        let mut capitalize_next = false;
        for ch in kebab.chars() {
            if ch == '-' {
                capitalize_next = true;
            } else if capitalize_next {
                result.push(ch.to_ascii_uppercase());
                capitalize_next = false;
            } else {
                result.push(ch);
            }
        }
        result
    }

    // -----------------------------------------------------------------------
    // Style / attribute helpers
    // -----------------------------------------------------------------------

    /// Build an inline style string from resolved properties, skipping semantics.
    fn build_style(props: &[ResolvedProperty]) -> String {
        let skip = ["content", "source", "a11y-label", "a11y-role", "a11y-hidden", "style"];
        let entries: Vec<String> = props
            .iter()
            .filter(|p| !skip.contains(&p.name.as_str()))
            .map(|p| {
                let css_name = &p.name; // already kebab-case
                let val = resolved_value_to_css(&p.value);
                format!("{css_name}:{val}")
            })
            .collect();
        entries.join(";")
    }

    /// Build the opening HTML tag for a primitive Mosaic node.
    ///
    /// Returns `(open_tag, close_tag)`. For self-closing tags the close tag is empty.
    fn primitive_open(tag: &str, props: &[ResolvedProperty]) -> (String, String) {
        let extra_style = Self::build_style(props);
        let class = props
            .iter()
            .find(|p| p.name == "style")
            .map(|p| match &p.value {
                ResolvedValue::Enum { namespace, member } => {
                    format!("mosaic-{namespace}-{member}")
                }
                ResolvedValue::String(s) => s.clone(),
                _ => String::new(),
            })
            .unwrap_or_default();

        match tag {
            "Box" => {
                let combined = combine_styles("", &extra_style);
                let open = format_html_div(&combined, &class, props);
                (open, "</div>".into())
            }
            "Stack" => {
                let base = "position:relative";
                let combined = combine_styles(base, &extra_style);
                let open = format_html_div(&combined, &class, props);
                (open, "</div>".into())
            }
            "Column" => {
                let base = "display:flex;flex-direction:column";
                let combined = combine_styles(base, &extra_style);
                let open = format_html_div(&combined, &class, props);
                (open, "</div>".into())
            }
            "Row" => {
                let base = "display:flex;flex-direction:row";
                let combined = combine_styles(base, &extra_style);
                let open = format_html_div(&combined, &class, props);
                (open, "</div>".into())
            }
            "Text" => {
                let mut attrs = String::new();
                if !extra_style.is_empty() {
                    attrs.push_str(&format!(" style=\"{extra_style}\""));
                }
                if !class.is_empty() {
                    attrs.push_str(&format!(" class=\"{class}\""));
                }
                (format!("<span{attrs}>"), "</span>".into())
            }
            "Image" => {
                let src = props
                    .iter()
                    .find(|p| p.name == "source")
                    .map(|p| resolved_value_to_css(&p.value))
                    .unwrap_or_default();
                let alt = props
                    .iter()
                    .find(|p| p.name == "a11y-label")
                    .map(|p| resolved_value_to_css(&p.value))
                    .unwrap_or_default();
                (format!("<img src=\"{src}\" alt=\"{alt}\">"), String::new())
            }
            "Spacer" => {
                let base = "flex:1";
                let combined = combine_styles(base, &extra_style);
                let open = format_html_div(&combined, &class, props);
                (open, "</div>".into())
            }
            "Scroll" => {
                let base = "overflow:auto";
                let combined = combine_styles(base, &extra_style);
                let open = format_html_div(&combined, &class, props);
                (open, "</div>".into())
            }
            "Divider" => ("<hr>".into(), String::new()),
            "Icon" => {
                let class_val = if class.is_empty() {
                    "icon".to_string()
                } else {
                    format!("icon {class}")
                };
                (format!("<span class=\"{class_val}\">"), "</span>".into())
            }
            "Grid" => {
                // Grid is special: it is self-contained — its content comes from
                // list slot bindings, not from nested child nodes. We build the
                // entire table HTML using `.map()` template literal expressions.
                //
                // The `headers` prop and `rows` prop are expected to be SlotRef
                // values pointing to list<text> slots. We extract the slot name
                // and build a self-contained table with JS map expressions.
                let headers_slot = props
                    .iter()
                    .find(|p| p.name == "headers" || p.name == "column-headers")
                    .and_then(|p| {
                        if let ResolvedValue::SlotRef { name, .. } = &p.value {
                            Some(name.clone())
                        } else {
                            None
                        }
                    })
                    .unwrap_or_else(|| "headers".to_string());

                let rows_slot = props
                    .iter()
                    .find(|p| p.name == "rows" || p.name == "viewport-rows")
                    .and_then(|p| {
                        if let ResolvedValue::SlotRef { name, .. } = &p.value {
                            Some(name.clone())
                        } else {
                            None
                        }
                    })
                    .unwrap_or_else(|| "rows".to_string());

                let headers_field = format!("this._{}", Self::to_camel_case(&headers_slot));
                let rows_field = format!("this._{}", Self::to_camel_case(&rows_slot));

                let style = Self::build_style(props);
                let style_attr = if style.is_empty() {
                    String::new()
                } else {
                    format!(" style=\"{style}\"")
                };

                // Build the table HTML with JS template literal expressions embedded.
                // Note: in Rust format strings, {{ and }} produce { and }. The
                // resulting string will contain `${…}` which is valid JavaScript
                // template literal syntax.
                let open = format!(
                    concat!(
                        "<table{style_attr}>",
                        "<thead><tr>",
                        "${{{headers_field}.map(h => `<th>${{{esc}(h)}}</th>`).join('')}}",
                        "</tr></thead>",
                        "<tbody>",
                        "${{{rows_field}.map(r => `<tr><td>${{{esc}(r)}}</td></tr>`).join('')}}",
                        "</tbody>",
                        "</table>"
                    ),
                    style_attr = style_attr,
                    headers_field = headers_field,
                    rows_field = rows_field,
                    esc = "this._escape",
                );

                // Self-contained: no close tag needed.
                (open, String::new())
            }
            _ => {
                // Unknown primitive: emit as a generic div.
                let combined = combine_styles("", &extra_style);
                let open = format_html_div(&combined, &class, props);
                (open, "</div>".into())
            }
        }
    }

    /// Get the content HTML for a Text node's `content` property.
    fn get_content(tag: &str, props: &[ResolvedProperty]) -> Option<String> {
        if tag != "Text" {
            return None;
        }
        props
            .iter()
            .find(|p| p.name == "content")
            .map(|p| resolved_value_to_html_content(&p.value))
    }

    // -----------------------------------------------------------------------
    // Fragment accumulation helpers
    // -----------------------------------------------------------------------

    /// Push a fragment onto the innermost open frame, or into root_frags.
    fn push_frag(&mut self, frag: HtmlFragment) {
        if let Some(frame) = self.stack.last_mut() {
            frame.inner.push(frag);
        } else {
            self.root_frags.push(frag);
        }
    }

    // -----------------------------------------------------------------------
    // Fragment serialization
    // -----------------------------------------------------------------------

    /// Serialize a list of fragments into a JavaScript template literal body.
    ///
    /// The serialization rules mirror the `HtmlFragment` variant documentation:
    ///
    /// - `Raw(s)` → append `s` verbatim.
    /// - `WhenOpen(slot)` → append `${this._<camel> ? \`` (ternary open).
    /// - `WhenClose` → append `` \` : ''}`` (ternary close).
    /// - `EachOpen(slot, item)` → append `${this._<camel>.map(<item> => \``
    /// - `EachClose` → append `` \`).join('')}``
    fn serialize_frags(frags: &[HtmlFragment]) -> String {
        let mut out = String::new();
        for frag in frags {
            match frag {
                HtmlFragment::Raw(s) => out.push_str(s),
                HtmlFragment::WhenOpen(slot) => {
                    let field = Self::to_camel_case(slot);
                    // Emit: ${this._field ? `
                    // The backtick after `?` opens the nested template string.
                    out.push_str(&format!("${{this._{field} ? `"));
                }
                HtmlFragment::WhenClose => {
                    // Close the true-branch template string and the ternary.
                    out.push_str("` : ''}");
                }
                HtmlFragment::EachOpen(slot, item) => {
                    let field = Self::to_camel_case(slot);
                    // Emit: ${this._field.map(_rawItem => { const item = this._escape(String(_rawItem)); return `
                    //
                    // Security: we shadow the raw loop variable with an escaped copy
                    // immediately, so every use of `item` inside the template body is
                    // HTML-safe. This prevents DOM XSS when list items contain `<` or `>`.
                    out.push_str(&format!(
                        "${{this._{field}.map(_raw_{item} => {{ const {item} = this._escape(String(_raw_{item})); return `"
                    ));
                }
                HtmlFragment::EachClose => {
                    // Close the return template string, the arrow-function body, and the map call.
                    out.push_str("`; }}).join('')}");
                }
            }
        }
        out
    }

    // -----------------------------------------------------------------------
    // Backing field generation
    // -----------------------------------------------------------------------

    /// Generate constructor backing-field initialization lines for all slots.
    ///
    /// Primitive scalar slots (text, number, bool, image, color) get a
    /// JavaScript attribute backing field. List and node slots get an array or
    /// null field and an explicit setter.
    fn generate_backing_fields(&self) -> (String, String) {
        let mut field_inits = Vec::new();
        let mut setters = Vec::new();

        for slot in &self.slots {
            let camel = Self::to_camel_case(&slot.name);
            match &slot.slot_type {
                MosaicType::Primitive(t) => {
                    let init = match t.as_str() {
                        "number" => "0".to_string(),
                        "bool" => "false".to_string(),
                        _ => "''".to_string(), // text, image, color → empty string
                    };
                    field_inits.push(format!("    this._{camel} = {init};"));
                }
                MosaicType::List(_) => {
                    field_inits.push(format!("    this._{camel} = [];"));
                    // Generate a setter so the host can push list data via JS.
                    setters.push(format!(
                        "  set {camel}(val) {{ this._{camel} = val ?? []; this._render(); }}"
                    ));
                }
                MosaicType::Component(_) => {
                    field_inits.push(format!("    this._{camel} = null;"));
                    setters.push(format!(
                        "  set {camel}(val) {{ this._{camel} = val ?? null; this._render(); }}"
                    ));
                }
            }
        }

        let fields_str = field_inits.join("\n");
        let setters_str = setters.join("\n");
        (fields_str, setters_str)
    }
}

impl Default for WebComponentRenderer {
    fn default() -> Self {
        Self::new()
    }
}

impl MosaicRenderer for WebComponentRenderer {
    fn begin_component(&mut self, name: &str, slots: &[MosaicSlot], _emits: &[MosaicEmit]) {
        self.component_name = name.to_string();
        self.slots = slots.to_vec();
    }

    fn end_component(&mut self) {}

    fn begin_node(&mut self, tag: &str, is_primitive: bool, props: &[ResolvedProperty]) {
        let (open, close) = if is_primitive {
            Self::primitive_open(tag, props)
        } else {
            // Non-primitive (composite component): use kebab-case custom element.
            let elem = Self::to_element_tag(tag);
            (format!("<{elem}>"), format!("</{elem}>"))
        };

        // Get direct text content for Text nodes.
        let content = if is_primitive { Self::get_content(tag, props) } else { None };

        // Push the opening tag as a Raw fragment into the *parent* frame (or root),
        // then push a new frame for this element's children.
        self.push_frag(HtmlFragment::Raw(open));

        let mut frame = HtmlFrame {
            close_tag: close,
            inner: Vec::new(),
        };

        // If this Text node has direct text content, pre-populate the frame.
        if let Some(text) = content {
            frame.inner.push(HtmlFragment::Raw(text));
        }

        self.stack.push(frame);
    }

    fn end_node(&mut self, _tag: &str) {
        if let Some(frame) = self.stack.pop() {
            // Serialize this frame's inner fragments.
            let inner = Self::serialize_frags(&frame.inner);
            let close = frame.close_tag;
            // Flush into parent (or root).
            self.push_frag(HtmlFragment::Raw(format!("{inner}{close}")));
        }
    }

    fn render_slot_child(&mut self, slot_name: &str, _slot_type: &MosaicType) {
        // Use a standard <slot> element for Shadow DOM content projection.
        // Security: HTML-escape the slot name before embedding it in an attribute
        // value. Slot names are constrained to identifier syntax by the analyzer,
        // but we escape at the output boundary for defence-in-depth.
        let escaped_name = html_escape_str(slot_name);
        let html = format!("<slot name=\"{escaped_name}\"></slot>");
        self.push_frag(HtmlFragment::Raw(html));
    }

    fn begin_when(&mut self, slot_name: &str) {
        // Emit a JavaScript ternary open: ${this._field ? `
        // The true-branch template literal is populated by subsequent fragments.
        self.push_frag(HtmlFragment::WhenOpen(slot_name.to_string()));
    }

    fn end_when(&mut self) {
        // Close the ternary: ` : ''}
        self.push_frag(HtmlFragment::WhenClose);
    }

    fn begin_each(&mut self, slot_name: &str, item_name: &str, _element_type: &MosaicType) {
        // Emit a JavaScript .map() open: ${this._field.map(item => `
        self.push_frag(HtmlFragment::EachOpen(
            slot_name.to_string(),
            item_name.to_string(),
        ));
    }

    fn end_each(&mut self) {
        // Close the map: `).join('')}
        self.push_frag(HtmlFragment::EachClose);
    }

    fn emit(self) -> EmitResult {
        let element_tag = Self::to_element_tag(&self.component_name);

        // --- observedAttributes ---
        // Only include primitive scalar slots (text, number, bool, image, color).
        // List and component slots are handled by JS setters, not HTML attributes.
        let observed: Vec<String> = self
            .slots
            .iter()
            .filter(|s| matches!(&s.slot_type, MosaicType::Primitive(_)))
            .map(|s| format!("'{}'", s.name))
            .collect();
        let observed_str = observed.join(", ");

        // --- Backing fields and setters ---
        let (backing_fields, setters_str) = self.generate_backing_fields();
        let setters_block = if setters_str.is_empty() {
            String::new()
        } else {
            format!("\n{setters_str}\n")
        };

        // --- HTML template body ---
        // Serialize all root-level fragments into the template literal body.
        let html_body = Self::serialize_frags(&self.root_frags);

        let output = format!(
            r#"// Auto-generated by mosaic-emit-webcomponent. Do not edit.

class {name} extends HTMLElement {{
  static get observedAttributes() {{ return [{observed}]; }}

  constructor() {{
    super();
    this.attachShadow({{ mode: 'open' }});
{fields}
  }}

  connectedCallback() {{ this._render(); }}
  attributeChangedCallback(name, _oldVal, newVal) {{
    this[`_${{this._toCamel(name)}}`] = newVal ?? '';
    this._render();
  }}
{setters}
  _render() {{
    this.shadowRoot.innerHTML = `{html}`;
  }}

  _escape(s) {{
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }}

  _toCamel(s) {{
    return s.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }}
}}
customElements.define('{tag}', {name});
"#,
            name = self.component_name,
            observed = observed_str,
            fields = backing_fields,
            setters = setters_block,
            html = html_body,
            tag = element_tag,
        );

        EmitResult {
            output,
            component_name: self.component_name,
        }
    }
}

// ===========================================================================
// Helpers
// ===========================================================================

/// Convert a `ResolvedValue` to a CSS value string.
fn resolved_value_to_css(v: &ResolvedValue) -> String {
    match v {
        ResolvedValue::String(s) => s.clone(),
        ResolvedValue::Number(n) => n.to_string(),
        ResolvedValue::Dimension(n, unit) => match unit.as_str() {
            "dp" | "sp" => format!("{n}px"),
            "%" => format!("{n}%"),
            _ => format!("{n}{unit}"),
        },
        ResolvedValue::Color(r, g, b, a) => {
            if *a == 255 {
                format!("rgb({r},{g},{b})")
            } else {
                let alpha = *a as f64 / 255.0;
                format!("rgba({r},{g},{b},{alpha:.3})")
            }
        }
        ResolvedValue::Bool(b) => b.to_string(),
        ResolvedValue::SlotRef { name, is_loop_var, .. } => {
            // Security: wrap all slot values with _escape() to prevent CSS injection
            // (e.g. `; behavior:url(evil)` or `</style>` break-out in style attributes).
            if *is_loop_var {
                // Loop variables: already a string from the host, escape for CSS context.
                format!("${{this._escape(String({name}))}}")
            } else {
                let camel = to_camel_case_free(name);
                format!("${{this._escape(String(this._{camel}))}}")
            }
        }
        ResolvedValue::Enum { namespace, member } => format!("{namespace}-{member}"),
    }
}

/// Convert a `ResolvedValue` to an HTML text content string (for Text nodes).
///
/// # Security
///
/// Slot references that resolve to runtime values are wrapped with
/// `this._escape()` so that any `<`, `>`, or `"` characters in the host-
/// supplied data are HTML-encoded before landing in `shadowRoot.innerHTML`.
///
/// Loop variables do not need an additional `_escape()` call here because
/// `EachOpen` serialization already shadows each loop variable with an escaped
/// copy at the start of every `.map()` arrow function.
fn resolved_value_to_html_content(v: &ResolvedValue) -> String {
    match v {
        ResolvedValue::String(s) => s.clone(),
        ResolvedValue::SlotRef { name, is_loop_var, .. } => {
            if *is_loop_var {
                // Safe: loop variables are pre-escaped by the EachOpen serializer.
                format!("${{{name}}}")
            } else {
                // Non-loop slot reference: wrap with _escape() to prevent DOM XSS.
                let camel = to_camel_case_free(name);
                format!("${{this._escape(String(this._{camel}))}}")
            }
        }
        other => resolved_value_to_css(other),
    }
}

/// HTML-escape a string for safe embedding in attribute values or element text.
///
/// Converts `&`, `<`, `>`, and `"` to their named HTML entities. Used at
/// code-generation time for identifiers that appear inside attribute values in
/// the generated HTML template string.
fn html_escape_str(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

/// Stand-alone kebab-to-camelCase conversion (mirrors the method on the struct).
fn to_camel_case_free(kebab: &str) -> String {
    let mut result = String::new();
    let mut capitalize_next = false;
    for ch in kebab.chars() {
        if ch == '-' {
            capitalize_next = true;
        } else if capitalize_next {
            result.push(ch.to_ascii_uppercase());
            capitalize_next = false;
        } else {
            result.push(ch);
        }
    }
    result
}

/// Combine two CSS style strings, inserting a semicolon separator as needed.
fn combine_styles(base: &str, extra: &str) -> String {
    match (base.is_empty(), extra.is_empty()) {
        (true, true) => String::new(),
        (true, false) => extra.to_string(),
        (false, true) => base.to_string(),
        (false, false) => format!("{base};{extra}"),
    }
}

/// Format an HTML `<div>` with optional style and class attributes.
fn format_html_div(style: &str, class: &str, props: &[ResolvedProperty]) -> String {
    let mut attrs = Vec::new();
    if !style.is_empty() {
        attrs.push(format!("style=\"{style}\""));
    }
    if !class.is_empty() {
        attrs.push(format!("class=\"{class}\""));
    }
    // Accessibility attributes.
    for p in props {
        match p.name.as_str() {
            "a11y-label" => attrs.push(format!("aria-label=\"{}\"", resolved_value_to_css(&p.value))),
            "a11y-role" => attrs.push(format!("role=\"{}\"", resolved_value_to_css(&p.value))),
            "a11y-hidden" => attrs.push(format!("aria-hidden=\"{}\"", resolved_value_to_css(&p.value))),
            _ => {}
        }
    }
    if attrs.is_empty() {
        "<div>".into()
    } else {
        format!("<div {}>", attrs.join(" "))
    }
}

// ===========================================================================
// Tests
// ===========================================================================

#[cfg(test)]
mod tests {
    use super::*;
    use mosaic_vm::MosaicVM;
    use mosaic_analyzer::analyze;

    fn emit(src: &str) -> String {
        let file = analyze(src).unwrap();
        let vm = MosaicVM::new(file);
        vm.run(WebComponentRenderer::new()).unwrap().output
    }

    // -----------------------------------------------------------------------
    // Test 1: Output contains class declaration
    // -----------------------------------------------------------------------

    #[test]
    fn test_class_declaration() {
        let out = emit(r#"component Button { Box { } }"#);
        assert!(out.contains("class Button extends HTMLElement"), "Missing class: {out}");
    }

    // -----------------------------------------------------------------------
    // Test 2: customElements.define with kebab-case tag
    // -----------------------------------------------------------------------

    #[test]
    fn test_custom_elements_define() {
        let out = emit(r#"component ProfileCard { Box { } }"#);
        assert!(
            out.contains("customElements.define('profile-card', ProfileCard)"),
            "Missing customElements.define: {out}"
        );
    }

    // -----------------------------------------------------------------------
    // Test 3: observedAttributes contains only scalar primitive slots
    // -----------------------------------------------------------------------

    #[test]
    fn test_observed_attributes() {
        let out = emit(r#"component Label { slot title: text; Text { content: @title; } }"#);
        assert!(out.contains("observedAttributes"), "Missing observedAttributes");
        assert!(out.contains("'title'"), "Missing scalar slot in observedAttributes: {out}");
    }

    // -----------------------------------------------------------------------
    // Test 4: observedAttributes excludes list<T> slots
    // -----------------------------------------------------------------------

    #[test]
    fn test_observed_excludes_list() {
        let out = emit(r#"
          component ItemList {
            slot items: list<text>;
            slot title: text;
            Column { }
          }
        "#);
        // 'title' (text, scalar) must be observed; 'items' (list) must not.
        assert!(out.contains("'title'"), "Expected 'title' in observedAttributes: {out}");
        assert!(!out.contains("'items'"), "List slot 'items' must NOT be in observedAttributes: {out}");
    }

    // -----------------------------------------------------------------------
    // Test 5: attachShadow present
    // -----------------------------------------------------------------------

    #[test]
    fn test_shadow_dom() {
        let out = emit(r#"component X { Box { } }"#);
        assert!(out.contains("attachShadow"), "Missing attachShadow: {out}");
    }

    // -----------------------------------------------------------------------
    // Test 6: _render method and shadowRoot.innerHTML present
    // -----------------------------------------------------------------------

    #[test]
    fn test_render_method() {
        let out = emit(r#"component X { Box { } }"#);
        assert!(out.contains("_render()"), "Missing _render method: {out}");
        assert!(out.contains("shadowRoot.innerHTML"), "Missing shadowRoot.innerHTML: {out}");
    }

    // -----------------------------------------------------------------------
    // Test 7: Column → flex column style
    // -----------------------------------------------------------------------

    #[test]
    fn test_column_style() {
        let out = emit(r#"component X { Column { } }"#);
        assert!(
            out.contains("flex-direction:column") || out.contains("flex-direction: column"),
            "Expected flex-direction:column: {out}"
        );
    }

    // -----------------------------------------------------------------------
    // Test 8: Row → flex row style
    // -----------------------------------------------------------------------

    #[test]
    fn test_row_style() {
        let out = emit(r#"component X { Row { } }"#);
        assert!(
            out.contains("flex-direction:row") || out.contains("flex-direction: row"),
            "Expected flex-direction:row: {out}"
        );
    }

    // -----------------------------------------------------------------------
    // Test 9: Slot reference as child → <slot> element
    // -----------------------------------------------------------------------

    #[test]
    fn test_slot_child_element() {
        let out = emit(r#"component Container { slot header: node; Column { @header; } }"#);
        assert!(out.contains("<slot name=\"header\">"), "Expected <slot name=\"header\">: {out}");
    }

    // -----------------------------------------------------------------------
    // Test 10: when block emits JS ternary, not <template data-when>
    // -----------------------------------------------------------------------

    #[test]
    fn test_when_ternary() {
        let out = emit(r#"
          component Cond {
            slot show: bool;
            Column {
              when @show {
                Text { content: "Hi"; }
              }
            }
          }
        "#);
        // Must contain a JS ternary expression, not a <template> tag.
        assert!(out.contains("? `"), "Expected ternary operator: {out}");
        assert!(out.contains(": ''}"), "Expected ternary false branch: {out}");
        assert!(!out.contains("data-when"), "Must NOT contain data-when: {out}");
        assert!(!out.contains("<template"), "Must NOT contain <template>: {out}");
    }

    // -----------------------------------------------------------------------
    // Test 11: each block emits JS .map(), not <template data-each>
    // -----------------------------------------------------------------------
    // list<text> parsing is now fixed; each block test is fully active.

    #[test]
    fn test_each_map() {
        let out = emit(r#"
          component List {
            slot items: list<text>;
            Column {
              each @items as item {
                Text { content: @item; }
              }
            }
          }
        "#);
        // Must contain .map() call, not <template data-each>.
        assert!(out.contains(".map("), "Expected .map(): {out}");
        assert!(out.contains(".join('')}"), "Expected .join('')}}: {out}");
        assert!(!out.contains("data-each"), "Must NOT contain data-each: {out}");
        assert!(!out.contains("<template"), "Must NOT contain <template>: {out}");
    }

    // -----------------------------------------------------------------------
    // Test 12: Grid emits <table> with .map() expressions
    // -----------------------------------------------------------------------

    #[test]
    fn test_grid_table() {
        let out = emit(r#"
          component DataTable {
            slot headers: list<text>;
            slot rows: list<text>;
            Grid { headers: @headers; rows: @rows; }
          }
        "#);
        assert!(out.contains("<table"), "Expected <table: {out}");
        assert!(out.contains("<thead"), "Expected <thead: {out}");
        assert!(out.contains("<tbody"), "Expected <tbody: {out}");
        assert!(out.contains(".map("), "Expected .map() in Grid: {out}");
        assert!(out.contains("_escape"), "Expected _escape in Grid: {out}");
    }

    // -----------------------------------------------------------------------
    // Test 13: Backing fields initialized in constructor
    // -----------------------------------------------------------------------

    #[test]
    fn test_backing_fields() {
        let out = emit(r#"
          component Widget {
            slot title: text;
            slot count: number;
            slot visible: bool;
            slot items: list<text>;
            Column { }
          }
        "#);
        // Text/number/bool slots get scalar backing fields.
        assert!(out.contains("this._title = ''"), "Expected _title init: {out}");
        assert!(out.contains("this._count = 0"), "Expected _count init: {out}");
        assert!(out.contains("this._visible = false"), "Expected _visible init: {out}");
        // List slot gets an array backing field.
        assert!(out.contains("this._items = []"), "Expected _items init: {out}");
    }

    // -----------------------------------------------------------------------
    // Test 14: List slot has a JS setter
    // -----------------------------------------------------------------------

    #[test]
    fn test_list_setter() {
        let out = emit(r#"
          component Widget {
            slot items: list<text>;
            Column { }
          }
        "#);
        assert!(out.contains("set items(val)"), "Expected setter: {out}");
        assert!(out.contains("this._items = val ?? []"), "Expected null guard: {out}");
    }

    // -----------------------------------------------------------------------
    // Test 15: _escape method is present in the class body
    // -----------------------------------------------------------------------

    #[test]
    fn test_escape_method() {
        let out = emit(r#"component X { Box { } }"#);
        assert!(out.contains("_escape(s)"), "Missing _escape: {out}");
        assert!(out.contains("&amp;"), "Missing &amp; escape: {out}");
        assert!(out.contains("&lt;"), "Missing &lt; escape: {out}");
        assert!(out.contains("&gt;"), "Missing &gt; escape: {out}");
        assert!(out.contains("&quot;"), "Missing &quot; escape: {out}");
    }
}
